Subject: `copyTextToClipboard` to make it easy to see that you have copied to the clipboard
Description: You can copy the URL of an issue by clicking `Copy Link`, but sometimes you think you have copied it, but you have not.
How about a little popup saying `Copied!` to make it easier to see that it has been copied?

Here is an example of a patch. 

<pre><code class="diff">
diff --git a/app/assets/javascripts/application.js b/app/assets/javascripts/application.js
index 320efd263..12e4aa5d2 100644
--- a/app/assets/javascripts/application.js
+++ b/app/assets/javascripts/application.js
@@ -589,6 +589,28 @@ function randomKey(size) {
   return key;
 }
 
+function copiedPopup() {
+  $('<div>')
+    .css({
+      position: 'absolute',
+      top: 0,
+      right: 0,
+      bottom: 0,
+      left: 0,
+      margin: 'auto',
+      height: 20,
+      width: 80,
+      'text-align': 'center'
+    })
+    .appendTo(document.body)
+    .text('Copied!')
+    .addClass('ui-state-default')
+    .delay(500)
+    .fadeOut(function() {
+      $(this).remove();
+    });
+}
+
 function copyTextToClipboard(target) {
   if (target) {
     var temp = document.createElement('textarea');
@@ -602,6 +624,7 @@ function copyTextToClipboard(target) {
     if ($(target).closest('.drdn.expanded').length) {
       $(target).closest('.drdn.expanded').removeClass("expanded");
     }
+    copiedPopup()
   }
   return false;
 }
</code></pre>
Status: New
Author: Abe Tomoaki

Subject: Focus on the textarea after clicking the Edit Journal button
Description: I suggest adding the feature to focus on the textarea after clicking on the Edit Journal button.

Here is a simple patch as follows.
<pre><code class="diff">
diff --git a/app/views/journals/edit.js.erb b/app/views/journals/edit.js.erb
index 96cf6b4f8..49fe4bec0 100644
--- a/app/views/journals/edit.js.erb
+++ b/app/views/journals/edit.js.erb
@@ -6,3 +6,13 @@ if ($("form#journal-<%= @journal.id %>-form").length > 0) {
 } else {
   $("#journal-<%= @journal.id %>-notes").after('<%= escape_javascript(render :partial => 'notes_form') %>');
 }
+
+// Focus on the textarea
+(() => {
+  const $textarea = $("#journal-<%= @journal.id %>-form .wiki-edit");
+  if ($textarea.length > 0) {
+    $textarea.focus();
+    const textareaLength = $textarea.val().length;
+    $textarea.get(0).setSelectionRange(textareaLength, textareaLength);
+  }
+})();
</code></pre>
Status: Closed
Author: Yasu Saku

